const envelope = $json.body ?? $json;
const e = envelope.event ?? envelope;
const eventId = envelope.event_id || e.event_id || e.client_msg_id || e.event_ts || (e.channel && e.ts ? `${e.channel}:${e.ts}` : '');
if (!eventId || !e.channel || !e.ts) throw new Error('Malformed Slack event');
const threadTs = e.thread_ts || e.ts;
const allowedSubtypes = [undefined, null, '', 'file_share', 'thread_broadcast'];
const email = ((e.user_profile && e.user_profile.email) || (e.user && e.user.profile && e.user.profile.email) || '').toLowerCase();
const internal = email.includes('baam.com') || email.includes('thehelpdeskteam.com');
const eligible = e.type === 'message'
  && !e.bot_id
  && !internal
  && e.user !== 'U_BRIDGE_BOT'
  && allowedSubtypes.includes(e.subtype);
return [{json: {
  event_id: eventId,
  channel: e.channel,
  ts: e.ts,
  thread_ts: threadTs,
  text: e.text || '',
  user: e.user || null,
  subtype: e.subtype || null,
  conversation_key: e.channel + ':' + threadTs,
  retry: envelope.demo_retry === true || e.demo_retry === true,
  eligible
}}];

const b = $json.body ?? $json;
const type = b.type || b.event_type || 'ticket.reply.created';
const ticketId = b.ticket_id || (b.ticket && b.ticket.id);
const text = (b.message && b.message.text) || b.text || b.body;
const eventId = b.event_id || b.id || (type + ':' + ticketId + ':' + Date.now());
if (!ticketId || !text) throw new Error('Malformed Modal event: ticket_id and message text are required');
return [{json: {event_id: eventId, ticket_id: ticketId, text: String(text)}}];

const checks = $('Load open checks').all().map((item) => item.json);
return $input.all().map((item) => {
  const e = item.json;
  const check = checks.find((row) => row.event_id === e.event_id) || {};
  const isBroadcast = check.subtype === 'thread_broadcast';
  const hasTicket = e.ticket_exists === true;
  const hasReceipt = e.receipt_exists === true;
  const hasRecord = e.record_exists === true;
  let kind = 'healthy';
  let detail = 'Ticket, receipt and reporting record verified';
  let allowed_actions = [];
  let recommended_action = null;

  if (e.is_slack_connect === true) {
    kind = 'slack_connect';
    detail = 'Slack Connect message - requires manual handling. The AI agent will not act on external users.';
  } else if (!hasTicket) {
    kind = isBroadcast ? 'broadcast_failed' : 'handoff_failed';
    detail = isBroadcast
      ? 'Thread broadcast has no root Modal ticket. Recreate the parent ticket from the source event.'
      : 'No Modal ticket exists for this Slack conversation. Recreate it from the source event.';
    allowed_actions = ['recreate_ticket', 'escalate'];
    recommended_action = 'recreate_ticket';
  } else if (!hasReceipt) {
    kind = isBroadcast ? 'broadcast_missing_receipt' : 'missing_receipt';
    detail = isBroadcast
      ? 'Thread broadcast root ticket exists, but the sync emoji is missing. Re-add the receipt reaction.'
      : 'Ticket exists, but the Slack sync receipt emoji is missing. Re-add the receipt reaction.';
    allowed_actions = ['readd_receipt', 'escalate'];
    recommended_action = 'readd_receipt';
  } else if (!hasRecord) {
    kind = 'reporting_gap';
    detail = 'Ticket and receipt exist, but the reporting record is absent. Rebuild the reporting record.';
    allowed_actions = ['rebuild_record', 'escalate'];
    recommended_action = 'rebuild_record';
  }

  if (kind !== 'healthy' && allowed_actions.length === 0) {
    allowed_actions = ['escalate'];
    recommended_action = 'escalate';
  }

  const evidence = {
    event_id: e.event_id,
    channel: e.channel,
    thread_ts: e.thread_ts,
    source_ts: e.source_ts,
    text: String(e.text || '').slice(0, 600),
    conversation_key: e.conversation_key,
    subtype: check.subtype || null,
    is_slack_connect: e.is_slack_connect === true,
    ticket_id: e.ticket_id || null,
    ticket_exists: hasTicket,
    receipt_exists: hasReceipt,
    record_exists: hasRecord,
    delivery_status: e.delivery_status || null,
  };

  const prompt = [
    'You are EchoBot, the independent sync verifier for a Slack to Modal support handoff.',
    'A sync check failed. Decide exactly ONE action, or escalate.',
    '',
    'EVIDENCE',
    `- event_id: ${evidence.event_id}`,
    `- channel: ${evidence.channel}`,
    `- subtype: ${evidence.subtype || 'none'}`,
    `- ticket_id: ${evidence.ticket_id || 'none'}`,
    `- ticket exists: ${evidence.ticket_exists}`,
    `- sync emoji exists: ${evidence.receipt_exists}`,
    `- reporting record exists: ${evidence.record_exists}`,
    `- slack connect user: ${evidence.is_slack_connect}`,
    `- source text: ${JSON.stringify(evidence.text)}`,
    '',
    `ALLOWED ACTIONS: ${allowed_actions.join(', ')}`,
    `RECOMMENDED: ${recommended_action || 'escalate'}`,
    '',
    'RULES',
    '- recreate_ticket: recreate the missing Modal ticket from the source event.',
    '- readd_receipt: re-add the :modal-48: Slack sync emoji to the source message.',
    '- rebuild_record: rebuild the missing Airtable reporting record.',
    '- escalate: Slack Connect, missing source, unsafe or ambiguous evidence, or a repeated failure.',
    '- Never invent ticket ids. Never message customers. Never delete data.',
    '- Prefer the recommended action when the evidence is complete.',
    '',
    'Return ONLY one JSON object and nothing else:',
    `{"action":"${recommended_action || 'escalate'}","diagnosis":"one short sentence"}`,
    'Do not repeat the evidence or this prompt.',
  ].join('\n');

  return {json: {...e, ...evidence, kind, detail, allowed_actions, recommended_action, evidence, prompt}};
});

const before = $('Classify the handoff').item.json;
const allowed = Array.isArray(before.allowed_actions) ? before.allowed_actions : ['escalate'];
function extract(response) {
  if (!response || typeof response !== 'object') return null;
  if (typeof response.output === 'string') return response.output;
  if (response.output && typeof response.output === 'object') return JSON.stringify(response.output);
  const raw = response.body?.message?.content;
  return typeof raw === 'string' ? raw : null;
}
let raw = extract($json);
let parsed = null;
if (raw) {
  raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { parsed = JSON.parse(raw); } catch {}
}
let action = parsed && (parsed.action ?? parsed.Action);
let diagnosis = parsed && (parsed.diagnosis ?? parsed.Diagnosis);
const validAction = typeof action === 'string' && allowed.includes(action);
const validDiagnosis = typeof diagnosis === 'string' && diagnosis.trim().length > 0 && diagnosis.length <= 500;
if (!validAction) action = 'escalate';
if (!validDiagnosis) diagnosis = 'AI remediation output was invalid or unavailable; escalating.';
const kind = ['healthy', 'progress'].includes(before.kind) ? 'handoff_failed' : before.kind;
const detail = action === 'escalate'
  ? `EchoBot AI could not safely resolve ${kind}: ${diagnosis} Evidence: ticket=${before.ticket_exists}, receipt=${before.receipt_exists}, record=${before.record_exists}.`
  : `EchoBot AI selected ${action}: ${diagnosis}`;
return [{json: {...before, action, diagnosis, ai_valid: validAction && validDiagnosis, kind, detail}}];

const before = $('Classify the handoff').item.json;
const decision = $('Parse remediation decision').item.json;
const e = $json;
const healthy = e.ticket_exists === true && e.receipt_exists === true && e.record_exists === true;
const improved = (before.ticket_exists === false && e.ticket_exists === true)
  || (before.receipt_exists === false && e.receipt_exists === true)
  || (before.record_exists === false && e.record_exists === true);
let kind = healthy ? 'healthy' : (improved ? 'progress' : (['healthy', 'progress'].includes(before.kind) ? 'handoff_failed' : before.kind));
let detail = healthy
  ? 'EchoBot AI remediation restored the ticket, receipt and reporting evidence.'
  : improved
    ? `EchoBot AI remediation made progress with ${decision.action}; the next pass will finish the remaining evidence.`
    : `EchoBot AI remediation could not restore the handoff with ${decision.action}. ${decision.diagnosis}`;
if (!healthy && !improved) {
  detail = `${detail} Evidence after the attempt: ticket=${e.ticket_exists}, receipt=${e.receipt_exists}, record=${e.record_exists}.`;
}
return [{json: {...e, kind, detail, action_attempted: decision.action, diagnosis: decision.diagnosis, before_kind: before.kind, improved, healthy}}];

const j = $json;
const kind = (typeof j.kind === 'string' && !['healthy', 'progress'].includes(j.kind)) ? j.kind : 'handoff_failed';
const detail = String(j.detail || 'EchoBot could not restore the handoff evidence.').slice(0, 1000);
return [{json: {event_id: j.event_id, kind, detail}}];

function extractContent(response) {
  if (!response || typeof response !== 'object') return null;
  if (typeof response.output === 'string') return response.output;
  if (response.output && typeof response.output === 'object') return JSON.stringify(response.output);
  const raw = response.body?.message?.content;
  return typeof raw === 'string' ? raw : null;
}
const KEYWORDS = ["urgen", "frustrat", "bad", "upset", "angry", "can't believe", "cannot believe", "let me down", "dissapoin", "anybody", "anyone?", "out there", "listening", "extendl", "furious", "livid", "outrag", "headache", "head ache", "annoy", "inconvenience", "nuisance", "exapser", "irrita", "piss", "shit", "fuck", "bitch", "losing customer", "lost customer", "losing client", "lost client", "losing business", "lost business", "asking you", "kidding me", "damn", "rude", "aggressive", "wtf", "insane", "hop on zoom", "get on phone", "call me", "get on zoom", "can we zoom", "can you zoom", "call number", "get on zoom", "drama", "I PAY FOR A SERVICE", "nobody showed", "expect to get it", "strike", "this is unacceptable", "scam", "Incorrect", "Unresolved"];
const c = $('Load target and earlier thread context').first().json;
const base = {event_id:c.event_id, model:c.model, policy_version:c.policy.version};
let content = extractContent($json);
let result = null;
if (content !== null) {
  content = content.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
  try { result = JSON.parse(content); } catch {}
}
const sentiment = result && (result.sentiment ?? result.Sentiment);
const reasoning = result && (result.reasoning ?? result.Reasoning);
const valid = !!result
  && ['Neutral','Negative'].includes(sentiment)
  && typeof reasoning === 'string'
  && reasoning.trim().length > 0
  && reasoning.length <= 1000;
const target = c.target || '';
const lower = target.toLowerCase();
const matched = KEYWORDS.filter((k) => lower.includes(k.toLowerCase()));
const triggerBased = matched.length > 0 && !lower.includes('badass');
if (!valid) {
  return [{json: {...base, ...c, valid:false, status:'error', sentiment:null,
    reasoning:'AI output was invalid or unavailable', evidence:'', keyword_matches:matched,
    trigger_based:triggerBased, review_required:true, review_reasons:['ai_unavailable'], alert_route:'none'}}];
}
const alertRoute = sentiment === 'Negative' ? 'quality-slack-alerts' : (triggerBased ? 'as-quality-sos' : 'none');
const reviewReasons = sentiment === 'Negative' ? ['ai_negative'] : (triggerBased ? ['keyword_fallback'] : []);
return [{json: {...base, ...c, valid:true, status:'complete', sentiment, reasoning,
  evidence:target, text:target, keyword_matches:matched, trigger_based:triggerBased,
  review_required:reviewReasons.length > 0, review_reasons:reviewReasons, alert_route:alertRoute}}];

const p=$('Build SOS quality alert').first().json;
const sos=$('Post SOS quality alert').first().json;
const link=(sos.message&&sos.message.permalink)||sos.permalink||'';
const raw='Slack Support Quality Alert for '+p.first_name+' '+p.last_name+'\n#'+p.channel_name+'\nIssue URL: '+p.permalink+'\nAS Alert Link:  '+link+'\nPost: '+p.target;
const message=raw.length>1600?raw.slice(0,1597)+'...':raw;
return [{json:{...p,message}}];
